<?php
require_once __DIR__.'/../../includes/auth.php';require_admin();require_once __DIR__.'/../../includes/ol_schema.php';require_once __DIR__.'/../../includes/ol_pdf.php';ensure_ol_schema();$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);$p=$id?query_one('SELECT * FROM ol_papers WHERE id=?','i',[$id]):null;if(!$p)exit('Paper not found');$file=realpath(__DIR__.'/../../'.ltrim($p['paper_file_path'],'/'));$db=db();$db->query('DELETE FROM ol_paper_questions WHERE paper_id='.(int)$id);$n=0;foreach(ol_extract_questions($file?ol_pdf_text($file):'') as $item){$st=$db->prepare('INSERT IGNORE INTO ol_paper_questions(paper_id,question_number,question_text,display_order) VALUES(?,?,?,?)');$st->bind_param('issi',$id,$item['number'],$item['text'],$n);$st->execute();$n++;}echo 'Extracted '.$n.' questions. <a href="../../ol-kuppiya/paper.php?subject_id='.$p['subject_id'].'&year='.$p['year'].'">Open paper</a>';
